def tick(sim, bodies, renderer, dt):
    e = sim.total_energy(bodies)
    sim.accelerations(bodies)
    sim.step(bodies, dt)
    frame = renderer.draw_all(bodies)
    return e, "\n".join(frame), renderer.stats_line(len(bodies), e)

def main():
    sim = NBody()
    renderer = Renderer()
    if MODE == "circular":
        bodies = make_circular_system(8)
    else:
        bodies = make_random_system(12, os.time())

    dt = 1 / FPS
    for _ in range(RUNS):
        tick(sim, bodies, renderer, dt)

    return len(bodies)

def kinetic_energy(self):
    v2 = self.vx * self.vx + self.vy * self.vy + self.vz * self.vz
    return 0.5 * self.mass * v2

def step(self, bodies, dt):
    for b in bodies:
        b.vx += b.ax * dt
        b.vy += b.ay * dt
        b.vz += b.az * dt

    for b in bodies:
        b.x += b.vx * dt
        b.y += b.vy * dt
        b.z += b.vz * dt

def total_energy(self, bodies):
    e = sum(b.kinetic_energy() for b in bodies)

    n = len(bodies)
    for i in range(n - 1):
        for j in range(i + 1, n):
            bi, bj = bodies[i], bodies[j]
            d = Vec3(bj.x - bi.x, bj.y - bi.y, bj.z - bi.z).length()
            e -= G * bi.mass * bj.mass / d

    return e

def length(self):
    d = (self.dot(self)) ** 0.5
    return d if d >= EPS else EPS

def normalize(self):
    d = self.length()
    if d <= EPS:
        return ZERO
    return self.scale(1.0 / d)

def draw_body(self, body):
    ix = int((body.x / 20.0 + 1.0) * (WIDTH - 1) / 2.0)
    iy = int((body.y / 20.0 + 1.0) * (HEIGHT - 1) / 2.0)
    mark = PALETTE[int(abs(body.mass) % len(PALETTE))]
    return (min(max(ix, 0), WIDTH - 1),
            min(max(iy, 0), HEIGHT - 1), mark)

def draw_all(self, bodies):
    grid = [[" "] * WIDTH for _ in range(HEIGHT)]
    for body in bodies:
        ix, iy, mark = self.draw_body(body)
        grid[iy][ix] = mark
    return ["".join(row) for row in grid]
